actions.script:
const L = (s) => ec.l10n.localize(s)
const data = ec.service.sync().name('org.moqui.call.CallHandlingServices.get#DialerData').requireNewTransaction(true).disableAuthz().call() || {}
ec.message.clearErrors()
phoneActive = !!data.phoneActive
callerIdText = Array.from(data.callerIdList || []).map((n) => n.phoneNumber + (n.description ? ' (' + n.description + ')' : '')).join(', ')
    || L('No number to call from; an administrator can give you one.')
hideText = data.hideCallerId ? L('Your number is hidden on calls you place (Settings, Call handling).') : ''
const when = (millis) => millis ? ec.l10n.format(new Date(Number(millis)), 'MMM d, h:mm a') : ''
recentList = Array.from(data.recentList || []).map((r) => ({number: r.number, whenText: when(r.whenMs)}))
searchText = String(text || '').trim()
resultList = []
numberText = ''
if (searchText) {
    const found = ec.service.sync().name('org.moqui.call.CallHandlingServices.search#Dialable').parameters({text: searchText, limit: 10})
        .requireNewTransaction(true).disableAuthz().call() || {}
    ec.message.clearErrors()
    numberText = found.number ? ec.resource.expand('${t} calls ${n}', '', {t: searchText, n: found.number}) : ''
    for (const r of Array.from(found.resultList || [])) for (const ph of Array.from(r.phoneList || []))
        resultList.push({name: r.name, number: ph.number, label: ph.label || ''})
}
searchForm = {text: searchText}
